// Simulations from fitted mixed models. The random stream is shared with the public R-compatible generators.
import { setSeed } from "../random/rng.js";
import { rnorm1 } from "../random/continuous.js";
import { rbinom1 } from "../random/binomial.js";
import { rpois1 } from "../random/poisson.js";
import { rgamma1 } from "../random/gamma.js";
import { logicalOption, lmerInternals, type LmerResult } from "./lmer.js";
import { glmerInternals, isGlmerFit, type GlmerResult } from "./glmer.js";
import type { RandomEffectsTerm } from "./mixedStructure.js";
// Generated by `node scripts/option-keys.mjs --write` from the option types; do not edit (begin)
import { checkOptions } from "../internal/checkOptions.js";
const SIMULATE_LMER_KEYS = ["nsim", "seed", "useU", "reForm"] as const;
const SIMULATE_GLMER_KEYS = ["nsim", "seed", "useU", "reForm"] as const;
// Generated by `node scripts/option-keys.mjs --write` (end)

/** Options of {@link simulateLmer} and {@link simulateGlmer}.
 *
 * @category Mixed models
 */
export interface MixedSimulateOptions {
  /** Number of simulated response vectors. Default 1. */
  nsim?: number;
  /** Set the shared R-compatible random stream before simulation. Null or omitted uses its current state. */
  seed?: number | null;
  /** Condition on all fitted random effects, or generate new effects. Cannot be combined with reForm. */
  useU?: boolean | number;
  /** Random-effects terms to condition on: null (all), "NA" or "~0" (none), or a formula selecting whole terms. */
  reForm?: string | null;
}

/** Simulations from a mixed-model fit: one response vector per simulation, with R's simulation column names.
 *
 * @category Mixed models
 */
export interface MixedSimulations extends Array<number[] | [number, number][]> {
  /** Names of the simulation columns, "sim_1", ... */
  names: string[];
}

function simulationCount(value: number | undefined): number {
  const n = value ?? 1;
  if (typeof n !== "number" || !Number.isFinite(n)) throw new TypeError("nsim must be a finite number");
  const k = Math.trunc(n);
  if (k < 1) throw new RangeError("(nsim <- as.integer(nsim[1])) > 0 is not TRUE");
  return k;
}

function selectedTerms(
  terms: readonly RandomEffectsTerm[],
  groups: readonly { name: string }[],
  reForm: string | null | undefined,
): Map<number, Set<number>> {
  if (reForm === undefined || reForm === "NA" || reForm === "~0" || reForm === "~0+0") return new Map();
  if (reForm === null) return new Map(terms.map((term, i) => [i, new Set(term.columns.map((_, j) => j))]));
  if (typeof reForm !== "string") throw new TypeError("reForm must be a formula, null, or \"NA\"");
  const compact = reForm.replace(/\s+/g, "");
  if (!compact.startsWith("~")) throw new SyntaxError("reForm must be a one-sided formula");
  const selected = new Map<number, Set<number>>();
  const pattern = /\(([^|]+)\|([^()]+)\)/g;
  for (const match of compact.matchAll(pattern)) {
    const lhs = match[1]!;
    const group = match[2]!;
    const intercept = !/(^|\+)0(\+|$)/.test(lhs) && !lhs.includes("-1");
    for (let i = 0; i < terms.length; i++) {
      const term = terms[i]!;
      if (groups[term.group]!.name.replace(/\s+/g, "") !== group) continue;
      const cols = selected.get(i) ?? new Set<number>();
      term.columns.forEach((name, j) => {
        if ((name === "(Intercept)" && intercept) || (name !== "(Intercept)" && lhs.includes(name))) cols.add(j);
      });
      if (cols.size > 0) selected.set(i, cols);
    }
  }
  if (selected.size === 0) throw new RangeError("reForm does not select a random-effects term in this fit");
  return selected;
}

/** Fill new random effects in Z-column order; terms and levels follow the fitted model structure. */
function newEffects(
  terms: readonly RandomEffectsTerm[],
  theta: readonly number[],
  groups: readonly { levels: readonly unknown[] }[],
  selected: ReadonlyMap<number, ReadonlySet<number>>,
  conditional: readonly number[],
  scale: number,
): number[] {
  const b = [...conditional];
  for (let ti = 0; ti < terms.length; ti++) {
    const term = terms[ti]!;
    const nc = term.columns.length;
    const conditioned = selected.get(ti) ?? new Set<number>();
    if (conditioned.size === nc) continue;
    const lower = Array.from({ length: nc }, () => new Array<number>(nc).fill(0));
    let k = term.thetaOffset;
    for (let j = 0; j < nc; j++) for (let i = j; i < nc; i++) lower[i]![j] = theta[k++]! * scale;
    for (let level = 0; level < groups[term.group]!.levels.length; level++) {
      const z = Array.from({ length: nc }, () => rnorm1(0, 1));
      for (let i = 0; i < nc; i++) {
        let value = 0;
        for (let j = 0; j <= i; j++) value += lower[i]![j]! * z[j]!;
        b[term.zOffset + level * nc + i] = conditioned.has(i) ? conditional[term.zOffset + level * nc + i]! : value;
      }
    }
  }
  return b;
}

function allTermsSelected(terms: readonly RandomEffectsTerm[], selected: ReadonlyMap<number, ReadonlySet<number>>): boolean {
  return terms.every((term, i) => (selected.get(i)?.size ?? 0) === term.columns.length);
}

/** Add the random-effects contribution Zb to a vector of fixed-effect predictors. */
function addRandomEffects(base: readonly number[], z: readonly { rows: number[]; values: number[] }[], b: readonly number[]): number[] {
  const out = [...base];
  for (let j = 0; j < z.length; j++) {
    const column = z[j]!;
    const value = b[j]!;
    for (let k = 0; k < column.rows.length; k++) out[column.rows[k]!]! += column.values[k]! * value;
  }
  return out;
}

/**
 * Simulations from a linear mixed-model fit. Equivalent to `lme4::simulate.merMod()` in R.
 *
 * @category Mixed models
 */
export function simulateLmer(fit: LmerResult, options: MixedSimulateOptions = {}): MixedSimulations {
  checkOptions(options, SIMULATE_LMER_KEYS, "simulateLmer"); // generated: option-keys.mjs
  if (typeof fit !== "object" || fit === null) throw new TypeError("fit must be a result returned by lmer");
  if (options.useU !== undefined && options.reForm !== undefined) {
    throw new Error("should specify only one of ‘use.u’ and ‘re.form’");
  }
  const n = simulationCount(options.nsim);
  if ((options.seed as unknown) === "NA") throw new Error("supplied seed is not a valid integer");
  if (options.seed !== undefined && options.seed !== null && typeof options.seed !== "number") throw new TypeError("seed must be a number or null");
  const useU = options.useU === undefined ? undefined : logicalOption(options.useU, false);
  const internals = lmerInternals(fit);
  const s = internals.structure;
  const selected = useU === true ? new Map(s.terms.map((term, i) => [i, new Set(term.columns.map((_, j) => j))])) : useU === false ? new Map<number, Set<number>>() : selectedTerms(s.terms, s.groups, options.reForm);
  if (options.seed !== undefined && options.seed !== null) setSeed(options.seed);
  const conditionedAll = allTermsSelected(s.terms, selected);
  const fittedRandom = conditionedAll ? [] : addRandomEffects(new Array<number>(fit.nObs).fill(0), s.z, internals.b);
  const fixed = conditionedAll ? fit.fitted : fit.fitted.map((v, i) => v - fittedRandom[i]!);
  const sims = [] as unknown as MixedSimulations;
  sims.names = [];
  // lme4 draws all new random effects for all replicates before drawing any response vectors.
  const effects: number[][] = [];
  for (let j = 0; j < n; j++) effects.push(newEffects(s.terms, internals.theta, s.groups, selected, internals.b, fit.sigma));
  for (let j = 0; j < n; j++) {
    const eta = conditionedAll ? fixed : addRandomEffects(fixed, s.z, effects[j]!);
    sims.push(eta.map((m) => rnorm1(m, fit.sigma)));
  }
  sims.names = Array.from({ length: n }, (_, j) => `sim_${j + 1}`);
  return sims;
}

/**
 * Simulations from a generalized linear mixed-model fit. Equivalent to R's `lme4::simulate.merMod()`.
 *
 * @category Mixed models
 */
export function simulateGlmer(fit: GlmerResult, options: MixedSimulateOptions = {}): MixedSimulations {
  checkOptions(options, SIMULATE_GLMER_KEYS, "simulateGlmer"); // generated: option-keys.mjs
  if (!isGlmerFit(fit)) throw new TypeError("fit must be a result returned by glmer");
  if (options.useU !== undefined && options.reForm !== undefined) {
    throw new Error("should specify only one of ‘use.u’ and ‘re.form’");
  }
  const n = simulationCount(options.nsim);
  if ((options.seed as unknown) === "NA") throw new Error("supplied seed is not a valid integer");
  if (options.seed !== undefined && options.seed !== null && typeof options.seed !== "number") throw new TypeError("seed must be a number or null");
  const useU = options.useU === undefined ? undefined : logicalOption(options.useU, false);
  const internals = glmerInternals(fit);
  const s = internals.structure;
  const selected = useU === true ? new Map(s.terms.map((term, i) => [i, new Set(term.columns.map((_, j) => j))])) : useU === false ? new Map<number, Set<number>>() : selectedTerms(s.terms, s.groups, options.reForm);
  if (options.seed !== undefined && options.seed !== null) setSeed(options.seed);
  const conditionedAll = allTermsSelected(s.terms, selected);
  const fittedRandom = conditionedAll ? [] : addRandomEffects(new Array<number>(fit.nObs).fill(0), s.z, internals.b);
  const fixedEta = conditionedAll ? internals.eta : internals.eta.map((v, i) => v - fittedRandom[i]!);
  const effects: number[][] = [];
  for (let j = 0; j < n; j++) effects.push(newEffects(s.terms, internals.theta, s.groups, selected, internals.b, 1));
  // R draws all random effects before discovering that inverse-Gaussian response simulation needs statmod.
  if (s.family.family === "inverse.gaussian") throw new Error("simulateGlmer: inverse.gaussian is not supported (R requires statmod)");
  const sims = [] as unknown as MixedSimulations;
  sims.names = [];
  for (let j = 0; j < n; j++) {
    const eta = conditionedAll ? fixedEta : addRandomEffects(fixedEta, s.z, effects[j]!);
    const mu = eta.map((v) => s.family.linkinv(v));
    if (s.family.family === "binomial") {
      const size = s.size ?? s.weights;
      if (s.size !== undefined) {
        sims.push(mu.map((p, i) => {
          const success = rbinom1(size[i]!, p);
          return [success, size[i]! - success] as [number, number];
        }));
      } else {
        sims.push(mu.map((p, i) => rbinom1(size[i]!, p) / size[i]!));
      }
    } else if (s.family.family === "poisson") {
      sims.push(mu.map((m) => rpois1(m)));
    } else if (s.family.family === "Gamma") {
      const shape = 1 / (fit.sigma * fit.sigma);
      sims.push(mu.map((m) => rgamma1(shape, m / shape)));
    } else {
      sims.push(mu.map((m) => rnorm1(m, fit.sigma)));
    }
  }
  sims.names = Array.from({ length: n }, (_, j) => `sim_${j + 1}`);
  return sims;
}
